{"jobs": [{"absolute_url": "https://careers.datadoghq.com/detail/5283132/?gh_jid=5283132", "data_compliance": [{"type": "gdpr", "requires_consent": false, "requires_processing_consent": false, "requires_retention_consent": false, "retention_period": null, "demographic_data_consent_applies": true}], "internal_job_id": 2647448, "location": {"name": "Amsterdam, The Netherlands; Dublin, Ireland"}, "metadata": [{"id": 33310, "name": "Time Type", "value": "Full time", "value_type": "single_select"}, {"id": 166208, "name": "Area - Engineering", "value": null, "value_type": "single_select"}, {"id": 498252, "name": "Cost Center", "value": "Sales - Commercial Sales", "value_type": "single_select"}, {"id": 516515, "name": "Geography", "value": "EMEA", "value_type": "single_select"}, {"id": 9593635, "name": "Early Career Time Type", "value": null, "value_type": "single_select"}, {"id": 29446322, "name": "Pay Transparency Range", "value": null, "value_type": "currency_range"}, {"id": 31273219, "name": "Does this role require access to ITAR-controlled data?", "value": null, "value_type": "single_select"}, {"id": 58619948, "name": "IC or MG", "value": "IC", "value_type": "single_select"}], "id": 5283132, "updated_at": "2026-09-03T08:26:14-04:00", "requisition_id": "R4787", "title": "Commercial Account Executive (DACH)", "company_name": "Datadog", "first_published": "2023-08-09T10:08:27-04:00", "language": "en", "application_deadline": null, "content": "&lt;p&gt;&lt;strong&gt;About Datadog:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Datadog is a best-in-class SaaS business, delivering a rare combination of growth, profitability, and stock market appreciation. &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Built by engineers, for engineers, our monitoring and security platform is used by organizations of all sizes across a wide range of industries to enable digital transformation, cloud migration, and infrastructure monitoring of our customers’ entire technology stack. We’re dedicated to creating, developing, and supporting our product and customers, allowing for seamless collaboration and problem-solving among Dev, Ops, and Security teams globally. &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Come join the team for an exciting opportunity to learn from top-level leaders and colleagues and grow alongside the company as we rapidly expand.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Team:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our sales team works with a best-of-breed product that solves real problems for our customers. Sellers follow a well-defined methodology that helps them identify the customer&#39;s unique needs and clearly convey the value of the Datadog product. Whether you&#39;re looking to learn from the best or be the best, the Datadog sales team is dedicated to furthering personal development and team success.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Opportunity:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Datadog is the monitoring and analytics platform for developers, IT teams and business users in the cloud age. We&#39;re scaling our Inside Sales team to help &lt;a href=&quot;https://www.datadoghq.com/customers/&quot; target=&quot;_blank&quot;&gt;IT and Technology leaders&lt;/a&gt; recognize Datadog’s impact in their digital transformation and migration to the cloud. This is an opportunity to bring a proven product, loved by thousands of customers, to a multi-billion dollar market.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You Will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Focus 100% on net new logo acquisition&lt;/li&gt;
&lt;li&gt;Manage the full sales cycle&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Run and partner with Sales Engineers on demos&lt;/li&gt;
&lt;li&gt;Use tools such as Sales Navigator and ZoomInfo&lt;/li&gt;
&lt;li&gt;Strategically prospect into CTOs, Engineering/IT Leaders, &amp;amp; technical end users&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;You Are:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Focused on hunting and closing net new logos&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A top performer with a history of success&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Bold on the phones, and creative in your emails&lt;/li&gt;
&lt;li&gt;Able to strategically map out and break into accounts&lt;/li&gt;
&lt;li&gt;Motivated, curious, hungry, and driven as a sales person&lt;/li&gt;
&lt;li&gt;Fluent in German&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Points:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Passionate about tech and the cloud space&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience with SaaS/Cloud and Salesforce&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Why You Should Apply:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Continuous career development and pathing opportunities&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Sales training in MEDDIC and Command of the Message&lt;/li&gt;
&lt;li&gt;Product training to develop an in-depth understanding of our product and space&lt;/li&gt;
&lt;li&gt;Best in breed onboarding&lt;/li&gt;
&lt;li&gt;Internal mentor and buddy program cross-departmentally&lt;/li&gt;
&lt;li&gt;New hire stock equity (RSUs) and employee stock purchase plan&lt;/li&gt;
&lt;li&gt;President’s Club for top performers&lt;/li&gt;
&lt;li&gt;Generous and competitive &lt;a href=&quot;https://www.datadoghq.com/global-benefits/&quot; target=&quot;_blank&quot;&gt;benefits&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Friendly and inclusive workplace culture&lt;/li&gt;
&lt;li&gt;Healthy work/life balance with discretionary unlimited paid time off&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;color: white;&quot;&gt;#LI-SB1&lt;/p&gt;
&lt;p style=&quot;color: white;&quot;&gt;#LI-Hybrid&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;hr&gt;
&lt;p&gt;&lt;strong&gt;About Datadog:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Datadog is the leading observability and security platform for the AI era, providing businesses with unified visibility across the technology stack to manage complexity at scale. It brings applications, infrastructure, data, models, and security into one place, using AI to detect and resolve issues before they impact customers. Trusted globally by Fortune 500 companies and high-growth AI leaders, Datadog enables businesses to move faster with clarity and confidence. Learn more about #DatadogLife on &lt;a href=&quot;https://www.instagram.com/datadoghq/?hl=en&quot; target=&quot;_blank&quot;&gt;Instagram&lt;/a&gt;, &lt;a href=&quot;https://www.linkedin.com/company/datadog&quot; target=&quot;_blank&quot;&gt;LinkedIn,&lt;/a&gt; and &lt;a href=&quot;https://learn.datadoghq.com/&quot; target=&quot;_blank&quot;&gt;Datadog Learning Center. &lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p data-renderer-start-pos=&quot;215&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Equal Opportunity at Datadog:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Datadog is proud to offer &lt;a href=&quot;https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12ScreenRdr.pdf&quot; target=&quot;_blank&quot;&gt;equal employment opportunity&lt;/a&gt; to everyone regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability, gender identity, veteran status, and other characteristics protected by law. We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. Here are our &lt;a href=&quot;https://www.datadoghq.com/legal/candidate-legal-notices/&quot; target=&quot;_blank&quot;&gt;Candidate Legal Notices&lt;/a&gt; for your reference.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Datadog endeavors to make our Careers Page accessible to all users. If you would like to contact us regarding the accessibility of our website or need assistance completing the application process, please complete &lt;a href=&quot;https://docs.google.com/forms/d/e/1FAIpQLSeoJeduEZ2NdZF_65uZmWUrCM-zee7yADXX1s6Xr9zAGq8iKA/viewform&quot; target=&quot;_blank&quot;&gt;this form&lt;/a&gt;. This form is for accommodation requests only and cannot be used to inquire about the status of applications.&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;662&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Privacy and AI Guidelines:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;662&quot;&gt;Any information you submit to Datadog as part of your application will be processed in accordance with Datadog’s&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.datadoghq.com/legal/applicant-candidate-privacy/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.datadoghq.com/legal/applicant-candidate-privacy/&quot; data-sk=&quot;tooltip_parent&quot;&gt;Applicant and Candidate Privacy Notice&lt;/a&gt;. For information on our AI policy, please visit &lt;a href=&quot;https://www.datadoghq.com/legal/interviewing-at-datadog-ai-guidelines/&quot; target=&quot;_blank&quot;&gt;Interviewing at Datadog AI Guidelines&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;", "departments": [{"id": 72275, "name": "Commercial Sales", "child_ids": [], "parent_id": 9021}], "offices": [{"id": 63481, "name": "Amsterdam", "location": "Amsterdam, Noord-Holland, Netherlands", "child_ids": [], "parent_id": 78096}, {"id": 25185, "name": "Dublin", "location": "Dublin, Ireland", "child_ids": [], "parent_id": 78095}], "ai_disclaimer": null, "include_ai_disclaimer": null, "ai_opt_out_request_url": null}]}
